#include <stdio.h>
int fib(int n) {
    if (n <= 1) return n;
    int a = 0, b = 1;
    for (int i = 0; i < n - 1; i++) {
        int temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}
int main(int argc, char *argv[]) {
    int n = atoi(argv[1]);
    printf("%d\n", fib(n));
    return 0;
}
